/*
 * <noam-audio-player> - the listen-and-download block on a blog post page.
 *
 * Register it in the site as a Custom Element (tag name: noam-audio-player,
 * source: this file's URL on the static asset host). A custom element runs inside
 * the page itself, so it can read the post slug from the address bar - unlike an
 * HTML embed, which lives in a cross-origin iframe.
 *
 * It asks /_functions/blogAudioInfo whether this post has audio. No autoplay:
 * nothing is fetched beyond that metadata call until the visitor presses play,
 * and no audio is ever generated by opening a page.
 *
 * Controls: play/pause, a seekable progress bar, elapsed and remaining time, and a
 * speed slider from 0.5x to 2x. Speed uses the browser's own playbackRate, so it
 * costs nothing and needs no second file. Every time shown reflects the chosen
 * speed, and the choice is remembered for the next post.
 */

(function () {
  var API = 'https://www.noamdoronmath.co.il/_functions/blogAudioInfo';
  var RATE_KEY = 'noam-audio-rate';
  var MIN_RATE = 0.5;
  var MAX_RATE = 2;

  function slugFromLocation() {
    var m = window.location.pathname.match(/\/post\/([^/?#]+)/);
    return m ? decodeURIComponent(m[1]) : null;
  }

  function mmss(sec) {
    sec = Math.max(0, Math.round(Number(sec) || 0));
    var m = Math.floor(sec / 60);
    var s = sec % 60;
    return m + ':' + (s < 10 ? '0' : '') + s;
  }

  function storedRate() {
    try {
      var v = Number(window.localStorage.getItem(RATE_KEY));
      if (v >= MIN_RATE && v <= MAX_RATE) return v;
    } catch (e) { /* private mode, or storage blocked */ }
    return 1;
  }

  function rememberRate(rate) {
    try { window.localStorage.setItem(RATE_KEY, String(rate)); } catch (e) { /* ignore */ }
  }

  function rateLabel(rate) {
    var s = (Math.round(rate * 100) / 100).toFixed(2);
    s = s.replace(/0+$/, '').replace(/\.$/, '');
    return s + '×';
  }

  var CSS = [
    ':host{display:block;direction:rtl;font-family:inherit;color:inherit}',
    '.wrap{border:1px solid rgba(128,128,128,.35);border-radius:16px;padding:14px 16px;margin:18px 0;',
    'background:rgba(128,128,128,.08)}',
    '.top{display:flex;align-items:center;gap:12px;flex-wrap:wrap;margin-bottom:10px}',
    '.label{font-weight:700;font-size:15px}',
    '.spacer{flex:1 1 auto}',
    'a.dl{font-size:13px;text-decoration:none;border:1px solid rgba(128,128,128,.5);border-radius:999px;',
    'padding:5px 13px;color:inherit;white-space:nowrap}',
    'a.dl:hover{background:rgba(128,128,128,.18)}',
    '.line{display:flex;align-items:center;gap:12px}',
    '.play{flex:0 0 auto;width:46px;height:46px;border-radius:50%;border:0;cursor:pointer;',
    'background:currentColor;display:flex;align-items:center;justify-content:center;padding:0}',
    '.play:focus-visible{outline:3px solid rgba(128,128,128,.7);outline-offset:3px}',
    '.play svg{width:20px;height:20px;display:block}',
    '.grow{flex:1 1 auto;min-width:0}',
    '.bar{display:block;width:100%}',
    '.times{display:flex;justify-content:space-between;font-size:12px;opacity:.75;margin-top:4px;',
    'font-variant-numeric:tabular-nums}',
    '.speed{display:flex;align-items:center;gap:10px;margin-top:12px;font-size:13px}',
    '.speed input{flex:1 1 auto;min-width:120px}',
    '.speed .val{font-weight:700;min-width:46px;text-align:center;font-variant-numeric:tabular-nums}',
    '.est{font-size:12px;opacity:.75;margin-top:6px}',
    'input[type=range]{accent-color:currentColor;height:24px;cursor:pointer}',
    '.hidden{display:none}',
    '@media (max-width:420px){.speed{flex-wrap:wrap}}',
  ].join('');

  var PLAY_ICON = '<svg viewBox="0 0 24 24" aria-hidden="true"><path fill="#fff" d="M8 5v14l11-7z"/></svg>';
  var PAUSE_ICON = '<svg viewBox="0 0 24 24" aria-hidden="true"><path fill="#fff" d="M6 5h4v14H6zm8 0h4v14h-4z"/></svg>';

  var TEMPLATE = [
    '<div class="wrap" part="wrap">',
    '  <div class="top">',
    '    <span class="label">גרסת שמע לפוסט</span>',
    '    <span class="spacer"></span>',
    '    <a class="dl" id="dl" download>הורדת MP3</a>',
    '  </div>',
    '  <div class="line">',
    '    <button class="play" id="play" type="button" aria-label="הפעלה"></button>',
    '    <div class="grow">',
    '      <input class="bar" id="bar" type="range" min="0" max="1000" value="0" step="1"',
    '             aria-label="מיקום בהקראה">',
    '      <div class="times"><span id="elapsed">0:00</span><span id="left">0:00</span></div>',
    '    </div>',
    '  </div>',
    '  <div class="speed">',
    '    <span>מהירות</span>',
    '    <input id="rate" type="range" min="0.5" max="2" step="0.05" value="1"',
    '           aria-label="מהירות הקראה">',
    '    <span class="val" id="rateval">1×</span>',
    '  </div>',
    '  <div class="est" id="est"></div>',
    '</div>',
  ].join('');

  function NoamAudioPlayer() {
    return Reflect.construct(HTMLElement, [], NoamAudioPlayer);
  }
  NoamAudioPlayer.prototype = Object.create(HTMLElement.prototype);
  NoamAudioPlayer.prototype.constructor = NoamAudioPlayer;
  Object.setPrototypeOf(NoamAudioPlayer, HTMLElement);

  NoamAudioPlayer.prototype.connectedCallback = function () {
    var host = this;
    if (host._wired) return;
    host._wired = true;

    var root = host.shadowRoot || host.attachShadow({ mode: 'open' });
    root.innerHTML = '<style>' + CSS + '</style>' + TEMPLATE;

    var wrap = root.querySelector('.wrap');
    var dl = root.querySelector('#dl');
    var playBtn = root.querySelector('#play');
    var bar = root.querySelector('#bar');
    var elapsedEl = root.querySelector('#elapsed');
    var leftEl = root.querySelector('#left');
    var rateInput = root.querySelector('#rate');
    var rateVal = root.querySelector('#rateval');
    var estEl = root.querySelector('#est');

    wrap.classList.add('hidden');
    playBtn.innerHTML = PLAY_ICON;

    var slug = host.getAttribute('slug') || slugFromLocation();
    if (!slug) return;

    var audio = new Audio();
    audio.preload = 'none';
    host._audio = audio;

    var declaredDuration = 0; // seconds, as recorded by the site
    var seeking = false;

    function duration() {
      return isFinite(audio.duration) && audio.duration > 0 ? audio.duration : declaredDuration;
    }

    function paint() {
      var total = duration();
      var rate = audio.playbackRate || 1;
      var at = audio.currentTime || 0;
      if (!seeking && total > 0) bar.value = String(Math.round((at / total) * 1000));
      elapsedEl.textContent = mmss(at / rate);
      leftEl.textContent = '−' + mmss(Math.max(0, (total - at) / rate));
      estEl.textContent = total > 0
        ? 'משך משוער במהירות ' + rateLabel(rate) + ': ' + mmss(total / rate)
        : '';
    }

    function applyRate(rate) {
      audio.playbackRate = rate;
      rateInput.value = String(rate);
      rateVal.textContent = rateLabel(rate);
      rememberRate(rate);
      paint();
    }

    playBtn.addEventListener('click', function () {
      if (audio.paused) {
        audio.play().catch(function () { /* the visitor can press again */ });
      } else {
        audio.pause();
      }
    });

    audio.addEventListener('play', function () {
      playBtn.innerHTML = PAUSE_ICON;
      playBtn.setAttribute('aria-label', 'השהייה');
    });
    audio.addEventListener('pause', function () {
      playBtn.innerHTML = PLAY_ICON;
      playBtn.setAttribute('aria-label', 'הפעלה');
    });
    audio.addEventListener('ended', function () {
      audio.currentTime = 0;
      paint();
    });
    audio.addEventListener('timeupdate', paint);
    audio.addEventListener('loadedmetadata', paint);
    audio.addEventListener('ratechange', paint);

    bar.addEventListener('input', function () {
      seeking = true;
      var total = duration();
      var rate = audio.playbackRate || 1;
      if (total > 0) {
        var at = (Number(bar.value) / 1000) * total;
        elapsedEl.textContent = mmss(at / rate);
        leftEl.textContent = '−' + mmss(Math.max(0, (total - at) / rate));
      }
    });
    bar.addEventListener('change', function () {
      var total = duration();
      if (total > 0) audio.currentTime = (Number(bar.value) / 1000) * total;
      seeking = false;
      paint();
    });

    rateInput.addEventListener('input', function () {
      applyRate(Number(rateInput.value));
    });

    fetch(API + '?slug=' + encodeURIComponent(slug), { credentials: 'omit' })
      .then(function (r) { return r.ok ? r.json() : null; })
      .then(function (info) {
        if (!info || !info.available || !info.src) return;
        declaredDuration = Number(info.durationSec) || 0;
        audio.src = info.src;
        dl.href = info.download || info.src;
        dl.setAttribute('download', slug + '.mp3');
        applyRate(storedRate());
        wrap.classList.remove('hidden');
      })
      .catch(function () { /* no audio block on failure - the post still reads normally */ });
  };

  NoamAudioPlayer.prototype.disconnectedCallback = function () {
    if (this._audio) this._audio.pause();
  };

  if (!window.customElements.get('noam-audio-player')) {
    window.customElements.define('noam-audio-player', NoamAudioPlayer);
  }
})();
